import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import net from 'node:net';
import { fileURLToPath } from 'node:url';

const SERVER = fileURLToPath(new URL('../server.mjs', import.meta.url));

function tmpDir() {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'bookings-test-'));
}

function run(env, cwd = tmpDir()) {
  const child = spawn(process.execPath, [SERVER], {
    cwd,
    env: { ...process.env, PORT: '0', ...env },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let stdout = '';
  let stderr = '';
  child.stdout.on('data', (d) => { stdout += d; });
  child.stderr.on('data', (d) => { stderr += d; });
  const exited = new Promise((resolve) => child.on('exit', (code) => resolve(code)));
  const ready = new Promise((resolve, reject) => {
    child.stdout.on('data', () => {
      const m = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n$/.exec(stdout);
      if (m) resolve(`http://127.0.0.1:${m[1]}`);
    });
    exited.then((code) => reject(new Error(`exited ${code}: ${stderr}`)));
  });
  return { child, ready, exited, out: () => stdout, err: () => stderr, cwd };
}

async function start(t, env = {}) {
  const dir = tmpDir();
  const s = run({ DATA_FILE: path.join(dir, 'data.json'), ...env }, dir);
  t.after(() => s.child.kill());
  s.base = await s.ready;
  s.dir = dir;
  return s;
}

async function req(base, method, url, body, headers = {}) {
  const opts = { method, headers };
  if (body !== undefined) {
    opts.body = typeof body === 'string' ? body : JSON.stringify(body);
    if (!('Content-Type' in headers)) opts.headers = { 'Content-Type': 'application/json', ...headers };
  }
  const res = await fetch(base + url, opts);
  const text = await res.text();
  return { status: res.status, type: res.headers.get('content-type'), text, json: text ? JSON.parse(text) : undefined };
}

